interface Notifier { void send(String msg); }
class EmailNotifier implements Notifier {...}

abstract class NotifierDecorator implements Notifier {
    protected final Notifier inner;
    NotifierDecorator(Notifier inner) { this.inner = inner; }
}
class LoggingNotifier extends NotifierDecorator {
    LoggingNotifier(Notifier inner) { super(inner); }
    public void send(String msg) {
        log("sending: " + msg);   // extra behaviour
        inner.send(msg);          // delegate
    }
}
class RetryNotifier extends NotifierDecorator {...}

Notifier n = new LoggingNotifier(new RetryNotifier(new EmailNotifier()));
